WITH m AS (SELECT start_id AS node_id, start_name AS node_name, start_of AS of FROM "@receipt-triples:transform_rows" WHERE start_type = 'Receipt' AND start_id <> '') SELECT node_id, node_id AS __corvic_surrogate_id, 'Receipt' AS node_type, min(node_name) AS name, min(json_extract_string(of, '$.order_number')) AS order_number, min(json_extract_string(of, '$.date')) AS date, min(json_extract_string(of, '$.subtotal')) AS subtotal, min(json_extract_string(of, '$.tax')) AS tax, min(json_extract_string(of, '$.total')) AS total, min(json_extract_string(of, '$.payment_method')) AS payment_method, min(json_extract_string(of, '$.document')) AS document, count(*) AS mention_count FROM m GROUP BY node_id